+      background:
+        radial-gradient(circle at top, rgba(95, 108, 255, 0.16), transparent 35%),
+        linear-gradient(180deg, #0a0f1e 0%, #090d18 100%);
+      color: var(--text);
+      padding: 24px;
+    }
+
+    .preview-card {
+      width: min(100%, 560px);
