+      border: 1px solid var(--line);
+      border-radius: 24px;
+      box-shadow: var(--shadow);
+      overflow: hidden;
+      backdrop-filter: blur(14px);
+    }
+
+    .preview-image {
+      display: block;
+      width: 100%;
+      aspect-ratio: 4 / 3;
+      object-fit: cover;
+      background: #0f1526;
+    }
+
+    .preview-content {
+      padding: 22px;
+      display: grid;
+      gap: 12px;
+    }
+
+    .title-row {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: 1.1rem;
+      letter-spacing: 0.01em;
+    }
+
+    .meta {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .trigger {
+      appearance: none;
+      border: 1px solid rgba(239, 83, 80, 0.35);
+      background: linear-gradient(180deg, rgba(239, 83, 80, 0.18), rgba(239, 83, 80, 0.1));
+      color: #ffdedd;
+      border-radius: 999px;
+      padding: 0.8rem 1.1rem;
+      font: inherit;
+      font-weight: 600;
+      cursor: pointer;
+      transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
+    }
+
+    .trigger:hover {
+      transform: translateY(-1px);
+      border-color: rgba(239, 83, 80, 0.55);
+      background: linear-gradient(180deg, rgba(239, 83, 80, 0.24), rgba(239, 83, 80, 0.14));
+    }
+
+    dialog {
+      width: min(92vw, 420px);
+      border: 1px solid var(--line);
+      border-radius: 20px;
+      padding: 0;
+      background: linear-gradient(180deg, #131a2f 0%, #0f1528 100%);
+      color: var(--text);
+      box-shadow: var(--shadow);
+    }
+
+    dialog::backdrop {
+      background: rgba(3, 6, 12, 0.72);
+      backdrop-filter: blur(6px);
+    }
+
+    .dialog-body {
+      padding: 24px;
+      display: grid;
+      gap: 14px;
+    }
+
+    .dialog-icon {
+      width: 46px;
+      height: 46px;
+      display: grid;
+      place-items: center;
+      border-radius: 14px;
+      background: rgba(239, 83, 80, 0.14);
+      color: var(--accent-strong);
+      font-size: 1.4rem;
+    }
+
+    .dialog-title {
+      margin: 0;
+      font-size: 1.2rem;
+    }
+
+    .dialog-copy {
+      margin: 0;
+      color: var(--muted);
+      line-height: 1.5;
+    }
+
+    .dialog-actions {
+      display: flex;
+      justify-content: flex-end;
+      gap: 10px;
+      padding-top: 4px;
+    }
+
+    .secondary,
+    .primary {
+      border-radius: 12px;
+      padding: 0.75rem 1rem;
+      font: inherit;
+      font-weight: 600;
+      cursor: pointer;
+      border: 1px solid transparent;
+    }
+
+    .secondary {
+      background: #1a2238;
+      color: var(--text);
+      border-color: rgba(255, 255, 255, 0.08);
+    }
+
+    .primary {
+      background: linear-gradient(180deg, #ff706d 0%, #e94d4a 100%);
+      color: white;
+      border-color: rgba(255, 255, 255, 0.06);
+    }
+
+    .secondary:hover,
+    .primary:hover {
+      filter: brightness(1.05);
+    }
+
+    .hidden-note {
+      position: absolute;
+      left: -9999px;
+    }
+  </style>
+</head>
+<body>
+  <main class="preview-card">
+    <img
+      class="preview-image"
+      src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80"
+      alt="Preview of a library image"
+    />
+    <div class="preview-content">
+      <div class="title-row">
+        <div>
+          <h1>Evening Library Shot</h1>
+          <p class="meta">Saved in your image library</p>
+        </div>
+        <button class="trigger" id="openDialog" type="button">Delete image</button>
+      </div>
+    </div>
+  </main>
+
+  <dialog id="deleteDialog" aria-labelledby="dialogTitle" aria-describedby="dialogDesc">
+    <div class="dialog-body">
+      <div class="dialog-icon" aria-hidden="true">!</div>
+      <div>
+        <h2 class="dialog-title" id="dialogTitle">Delete this image?</h2>
+        <p class="dialog-copy" id="dialogDesc">
+          This will remove the image from your library and it cannot be undone.
+        </p>
+      </div>
+      <div class="dialog-actions">
+        <button class="secondary" id="cancelDialog" type="button">Cancel</button>
+        <button class="primary" id="confirmDelete" type="button">Delete</button>
+      </div>
+    </div>
+  </dialog>
+
+  <script>
+    const dialog = document.getElementById('deleteDialog');
+    const openDialog = document.getElementById('openDialog');
+    const cancelDialog = document.getElementById('cancelDialog');
+    const confirmDelete = document.getElementById('confirmDelete');
+    const previewCard = document.querySelector('.preview-card');
+
+    openDialog.addEventListener('click', () => {
+      dialog.showModal();
+    });
+
+    cancelDialog.addEventListener('click', () => {
+      dialog.close();
+    });
+
+    confirmDelete.addEventListener('click', () => {
+      dialog.close();
+      previewCard.innerHTML = `
+        <div class="preview-content" style="padding: 42px 22px; text-align: center;">
+          <h1 style="margin: 0;">Image deleted</h1>
+          <p class="meta" style="margin: 8px 0 0;">The file has been removed from your library.</p>
+        </div>
+      `;
+    });
+
+    dialog.addEventListener('click', (event) => {
+      const rect = dialog.getBoundingClientRect();
+      const clickedBackdrop =
+        event.clientX < rect.left ||
+        event.clientX > rect.right ||
+        event.clientY < rect.top ||
+        event.clientY > rect.bottom;
+
+      if (clickedBackdrop) {
+        dialog.close();
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
