      --panel: #11182d;
      --panel-2: #18213a;
      --text: #e7ebf7;
      --muted: #95a0bc;
      --line: rgba(255, 255, 255, 0.08);
      --accent: #ef5350;
      --accent-strong: #ff6b68;
