         <div>
           <h1>Evening Library Shot</h1>
           <p class="meta">Saved in your image library</p>
         </div>
         <button class="trigger" id="openDialog" type="button">Delete image</button>
       </div>
     </div>
   </main>

   <dialog id="deleteDialog" aria-labelledby="dialogTitle" aria-describedby="dialogDesc">
     <div class="dialog-body">
       <div class="dialog-icon" aria-hidden="true">!</div>
       <div>
         <h2 class="dialog-title" id="dialogTitle">Delete this image?</h2>
         <p class="dialog-copy" id="dialogDesc">
           This will remove the image from your library and it cannot be undone.
         </p>
       </div>
       <div class="dialog-actions">
         <button class="secondary" id="cancelDialog" type="button">Cancel</button>
         <button class="primary" id="confirmDelete" type="button">Delete</button>
       </div>
     </div>
   </dialog>

   <script>
     const dialog = document.getElementById('deleteDialog');
     const openDialog = document.getElementById('openDialog');
     const cancelDialog = document.getElementById('cancelDialog');
     const confirmDelete = document.getElementById('confirmDelete');
     const previewCard = document.querySelector('.preview-card');

     openDialog.addEventListener('click', () => {
       dialog.showModal();
     });

     cancelDialog.addEventListener('click', () => {
       dialog.close();
     });

     confirmDelete.addEventListener('click', () => {
       dialog.close();
       previewCard.innerHTML = `
         <div class="preview-content" style="padding: 42px 22px; text-align: center;">
           <h1 style="margin: 0;">Image deleted</h1>
           <p class="meta" style="margin: 8px 0 0;">The file has been removed from your library.</p>
         </div>
       `;
     });

     dialog.addEventListener('click', (event) => {
       const rect = dialog.getBoundingClientRect();
       const clickedBackdrop =
         event.clientX < rect.left ||
         event.clientX > rect.right ||
         event.clientY < rect.top ||
         event.clientY > rect.bottom;

       if (clickedBackdrop) {
         dialog.close();
       }
     });
   </script>
 </body>
 </html>

')
